//! ⚠️ Actor failure publications retain a causal call reference instead of masquerading as registered jobs.
use super::*;
use semio_framework_actor::{ActorFailureCallReference,ActorFailureCallKind,ActorFailureOutcome,ActorFailureChunk,ActorFailureCallFailure};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum ActorFailureStatus{Signal,Publish{outcome:Option<ActorFailureOutcome>},Read{chunk:Option<ActorFailureChunk>},AcknowledgeChunk{acknowledged:bool},Acknowledge{acknowledged:bool}}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct ActorFailureCall{pub input:RetainedTurnInput,pub spent:RetainedCloneProgress,pub work_units_spent:u64,pub reference:ActorFailureCallReference,pub status:ActorFailureStatus,pub refusal:Option<ActorFailureCallFailure>}
pub struct ActorFailureFixedReceipt{bytes:[u8;184]}
impl ActorFailureFixedReceipt{
 pub const fn empty()->Self{Self{bytes:[0;184]}}pub fn bytes(&self)->&[u8;184]{&self.bytes}pub fn write(&mut self,call:ActorFailureCall,escrow:OriginalEscrowExtent)->Result<(),ValueError>{Self::write_to(&mut OriginalSliceHeaderWriter::new(&mut self.bytes,184)?,call,escrow)}
 pub fn write_to(sink:&mut impl OriginalEscrowHeaderWrite,call:ActorFailureCall,escrow:OriginalEscrowExtent)->Result<(),ValueError>{call.reference.validate()?;if match call.status{ActorFailureStatus::Signal=>call.reference.failed_epoch!=call.input.epoch,_=>call.reference.failed_epoch>=call.input.epoch}{return Err(invalid())}let(tag,authority)=match call.refusal{None=>(0,None),Some(ActorFailureCallFailure::Authority(kind))=>(1,Some(kind)),Some(ActorFailureCallFailure::Semantic)=>(2,None)};let mut body=[call.reference.failed_epoch,call.reference.call_kind.tag(),0,0];let(kind,flags)=match call.status{ActorFailureStatus::Signal=>{if call.refusal!=Some(ActorFailureCallFailure::Semantic){return Err(invalid())}(0,0)},ActorFailureStatus::Publish{outcome}=>{if let Some(outcome)=outcome{outcome.validate()?;if outcome.reference!=call.reference{return Err(invalid())}body[2]=outcome.byte_length;}(1,u8::from(outcome.is_some()))},ActorFailureStatus::Read{chunk}=>{let flags=if let Some(chunk)=chunk{if chunk.byte_length==Some(0){return Err(invalid())}body[2]=chunk.offset;body[3]=chunk.byte_length.unwrap_or(0);1|(u8::from(chunk.byte_length.is_some())<<1)|(u8::from(chunk.output_closed)<<2)}else{0};(2,flags)},ActorFailureStatus::AcknowledgeChunk{acknowledged}=>(3,u8::from(acknowledged)),ActorFailureStatus::Acknowledge{acknowledged}=>(4,u8::from(acknowledged))};sink.write(&[b'S',b'A',b'F',b'1',kind,flags,tag,0])?;OriginalActorFixedReceipt::write_to(sink,OriginalActorFixedCall{input:call.input,spent:call.spent,work_units_spent:call.work_units_spent,kind:OriginalActorFixedKind::Failure{authority}},escrow)?;for value in body{sink.write(&value.to_le_bytes())?}Ok(())}
 pub fn read(bytes:&[u8])->Result<(ActorFailureCall,OriginalEscrowExtent),ValueError>{if bytes.len()!=184||&bytes[..4]!=b"SAF1"||bytes[7]!=0{return Err(invalid())}let(actor,escrow)=OriginalActorFixedReceipt::read(&bytes[8..152])?;let OriginalActorFixedKind::Failure{authority}=actor.kind else{return Err(invalid())};let refusal=match(bytes[6],authority){(0,None)=>None,(1,Some(kind))=>Some(ActorFailureCallFailure::Authority(kind)),(2,None)=>Some(ActorFailureCallFailure::Semantic),_=>return Err(invalid())};let word=|at|u64::from_le_bytes(bytes[at..at+8].try_into().unwrap());let reference=ActorFailureCallReference{failed_epoch:word(152),call_kind:ActorFailureCallKind::from_tag(word(160))?};reference.validate()?;let a=word(168);let b=word(176);let flags=bytes[5];let status=match bytes[4]{0 if flags==0&&a==0&&b==0&&refusal==Some(ActorFailureCallFailure::Semantic)=>ActorFailureStatus::Signal,1 if flags<=1&&b==0=>{let outcome=if flags==0{if a!=0{return Err(invalid())}None}else{let value=ActorFailureOutcome{reference,byte_length:a};value.validate()?;Some(value)};ActorFailureStatus::Publish{outcome}},2 if matches!(flags,0|1|3|5|7)=>{let chunk=if flags==0{if a!=0||b!=0{return Err(invalid())}None}else{if (flags&2==0&&b!=0)||(flags&2!=0&&b==0){return Err(invalid())}Some(ActorFailureChunk{offset:a,byte_length:(flags&2!=0).then_some(b),output_closed:flags&4!=0})};ActorFailureStatus::Read{chunk}},3 if flags<=1&&a==0&&b==0=>ActorFailureStatus::AcknowledgeChunk{acknowledged:flags==1},4 if flags<=1&&a==0&&b==0=>ActorFailureStatus::Acknowledge{acknowledged:flags==1},_=>return Err(invalid())};if match status{ActorFailureStatus::Signal=>reference.failed_epoch!=actor.input.epoch,_=>reference.failed_epoch>=actor.input.epoch}{return Err(invalid())}Ok((ActorFailureCall{input:actor.input,spent:actor.spent,work_units_spent:actor.work_units_spent,reference,status,refusal},escrow))}
}
